s1-armstrong-numbers.code:
// Approach: Count decimal digits, then sum each digit raised to that count; compare with the original
//   number.
bool isArmstrong(int n) {
    if (n < 0) return false;
    int digits = 0, t = n;
    do { ++digits; t /= 10; } while (t);          // count how many digits n has
    long long sum = 0;
    t = n;
    do {
        int digit = t % 10;
        long long power = 1;
        for (int i = 0; i < digits; ++i) power *= digit;  // digit raised to (digit count)
        sum += power;
        t /= 10;
    } while (t);
    return sum == n;                               // Armstrong iff that sum equals n
}

s1-check-for-prime.code:
// Approach: Check divisors only up to √n. The linked GFG minimum-jumps page is unrelated; the CN/TUF
//   links match this prime-check lesson.
bool isPrime(int n) {
    if (n < 2) return false;                        // 0 and 1 aren't prime
    for (int d = 2; d <= n / d; ++d)                 // only need to check up to sqrt(n)
        if (n % d == 0) return false;                // found a factor -> not prime
    return true;
}

s1-check-palindrome.code:
// Approach: Reverse only the last half of the digits, then compare both halves.
bool isPalindrome(int n) {
    if (n < 0 || (n != 0 && n % 10 == 0)) return false;
    int reversedHalf = 0;
    // Stop halfway to avoid reversing the whole number (and overflow).
    while (n > reversedHalf) {
        reversedHalf = reversedHalf * 10 + n % 10;
        n /= 10;
    }
    // For odd digit counts, ignore the middle digit in reversedHalf.
    return n == reversedHalf || n == reversedHalf / 10;
}

s1-count-digits.code:
// Approach: Count decimal digits by repeated division; zero has one digit. The linked GFG task
//   instead counts nonzero digits that divide the original number.
int countDigits(int n) {
    int digits = 0;
    do { ++digits; n /= 10; } while (n != 0);
    return digits;
}
int countDividingDigits(int n) {
    int original = n, value = n, answer = 0;
    while (value > 0) {
        int digit = value % 10;
        if (digit != 0 && original % digit == 0) ++answer;
        value /= 10;
    }
    return answer; // linked GFG variant, for positive n
}

s1-counting-frequencies-of-array-element.code:
// Approach: Increment a hash-map count for each value; the map is the frequency table.
#include <unordered_map>
#include <vector>
using namespace std;
unordered_map<int, int> frequencies(const vector<int>& arr) {
    unordered_map<int, int> count;
    for (int value : arr) ++count[value];  // bump this value's count by one
    return count;
}

s1-gcd-or-hcf.code:
// Approach: Euclid's algorithm repeatedly replaces (a,b) with (b,a mod b). Normalize signs so the HCF
//   is nonnegative.
long long gcdHcf(int a, int b) {
    long long x = a, y = b;
    if (x < 0) x = -x;
    if (y < 0) y = -y;
    while (y != 0) {
        long long remainder = x % y;
        x = y;
        y = remainder;
    }
    return x;
}

s1-print-all-divisors.code:
// Approach: Divisors of n come in pairs around √n. The linked GFG task instead sums divisors of every
//   integer from 1 to n.
#include <algorithm>
#include <vector>
using namespace std;
vector<int> divisors(int n) {
    vector<int> result;
    if (n <= 0) return result;
    for (int d = 1; d <= n / d; ++d)
        if (n % d == 0) {
            result.push_back(d);
            if (d != n / d) result.push_back(n / d);
        }
    sort(result.begin(), result.end());
    return result;
}
long long sumOfAllDivisorsUpTo(int n) {
    long long answer = 0;
    for (int divisor = 1; divisor <= n; ++divisor)
        answer += 1LL * divisor * (n / divisor);
    return answer; // d divides floor(n/d) numbers up to n
}

s1-reverse-a-number.code:
// Approach: Move one digit at a time into the reversed number, checking the 32-bit boundary before
//   multiplying by ten.
#include <climits>
int reverseNumber(int n) {
    int reversed = 0;
    while (n != 0) {
        int digit = n % 10;
        if (reversed > INT_MAX / 10 ||
            (reversed == INT_MAX / 10 && digit > 7) ||
            reversed < INT_MIN / 10 ||
            (reversed == INT_MIN / 10 && digit < -8))
            return 0; // LeetCode requires zero on overflow
        reversed = reversed * 10 + digit;
        n /= 10;
    }
    return reversed;
}

s1-understand-recursion-by-print-somethi.code:
// Approach: Every call does one unit of work, reduces n by one, and stops at zero; the base case
//   prevents infinite recursion.
#include <iostream>
#include <string>
using namespace std;
void printNTimes(const string& message, int n, ostream& out) {
    if (n <= 0) return;
    out << message << '\n';
    printNTimes(message, n - 1, out);
}

