s1-print-1-to-n-using-recursion.code:
// Approach: Recurse to n-1 before outputting n, so the values appear in ascending order.
#include <vector>
using namespace std;
void collect1ToN(int n, vector<int>& out) {
    if (n <= 0) return;
    // Smaller values are added first as the recursion returns.
    collect1ToN(n - 1, out);
    out.push_back(n);
}

