// Approach: The lesson sums 1 through n recursively. The linked GFG task asks for the sum of cubes,
//   equal to (n(n+1)/2)².
long long sumFirstN(int n) {
    if (n <= 0) return 0;
    return n + sumFirstN(n - 1);
}
long long sumFirstNCubes(long long n) {
    if (n <= 0) return 0;
    long long triangle = n * (n + 1) / 2;
    return triangle * triangle; // when answer fits long long
}

s1-reverse-an-array.code:
// Approach: Swap the outer pair and move both pointers inward until they cross.
#include <algorithm>
#include <vector>
using namespace std;
void reverseArray(vector<int>& a) {
    int left = 0, right = static_cast<int>(a.size()) - 1;
    // Each swap puts two values in their final reversed positions.
    while (left < right) {
        swap(a[left], a[right]);
        ++left;
        --right;
    }
}

s1-check-if-a-string-is-palindrome-or-no.code:
// Approach: Compare from both ends. The linked LeetCode Valid Palindrome variant ignores punctuation
//   and letter case.
#include <cctype>
#include <string>
using namespace std;
bool isPalindromeString(const string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right)
        if (s[left++] != s[right--]) return false;
    return true;
}
bool isValidPalindrome(const string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) {
        while (left < right && !isalnum((unsigned char)s[left])) ++left;
        while (left < right && !isalnum((unsigned char)s[right])) --right;
        if (left >= right) break;
        if (tolower((unsigned char)s[left++]) !=
            tolower((unsigned char)s[right--])) return false;
    }
    return true;
}

s1-fibonacci-number.code:
// Approach: Keep only the two previous Fibonacci numbers.
#include <vector>
using namespace std;
long long fibonacci(int n) {
    if (n <= 0) return 0;
    long long previous = 0, current = 1;
    // The next term needs only the two terms immediately before it.
    for (int i = 2; i <= n; ++i) {
        long long next = previous + current;
        previous = current;
        current = next;
    }
    return current;
}

s1-find-the-highest-lowest-frequency-ele.code:
// Approach: Count each value, then scan the counts for the most and least frequent.
#include <unordered_map>
#include <utility>
#include <vector>
using namespace std;
pair<int, int> highestLowestFrequency(const vector<int>& values) {
    if (values.empty()) return {-1, -1};
    unordered_map<int, int> frequency;
    for (int value : values) ++frequency[value];
    int highest = values[0], lowest = values[0];
    // On equal frequencies, choose the smaller value consistently.
    for (const auto& entry : frequency) {
        int value = entry.first, count = entry.second;
        if (count > frequency[highest] ||
            (count == frequency[highest] && value < highest))
            highest = value;
        if (count < frequency[lowest] ||
            (count == frequency[lowest] && value < lowest))
            lowest = value;
    }
    return {highest, lowest};
}

