s1-switch-statement.code:
// Approach: Switch on the choice: 1 uses circle area πr², and 2 uses rectangle area length×breadth,
//   as in the linked practice task.
#include <vector>
using namespace std;
double switchCase(int choice, const vector<double>& dimensions) {
    const double PI = 3.14159265358979323846;
    switch (choice) {
        case 1: return PI * dimensions[0] * dimensions[0];
        case 2: return dimensions[0] * dimensions[1];
        default: return 0.0;
    }
}

