    for (int value : values) sum += value;
    return sum;
}
string reverseText(string text) {
    for (int left = 0, right = (int)text.size() - 1; left < right; ++left, --right) {
        char temp = text[left]; text[left] = text[right]; text[right] = temp;
    }
    return text;
}

