s1-while-loops.code:
// Approach: Use a while loop while a condition remains true; update its state to ensure it
//   terminates.
int digitSum(int number) {
    long long value = number;
    if (value < 0) value = -value;
    int sum = 0;
    while (value > 0) {
        sum += value % 10;
        value /= 10; // remove one digit
    }
    return sum;
}

