    b += 2;                  // b aliases the caller's variable
    return {valueResult, b};
}

s1-time-complexity-learn-basics-and-then.code:
// Approach: Count how often the dominant operation runs; nested full loops multiply, while
//   consecutive loops add.
#include <vector>
using namespace std;
long long countEqualPairs(const vector<int>& values) {
    long long pairs = 0;
    for (int i = 0; i < (int)values.size(); ++i)
        for (int j = i + 1; j < (int)values.size(); ++j)
            if (values[i] == values[j]) ++pairs;
    return pairs; // about n(n-1)/2 comparisons
}

