s1-factorial-of-n-numbers.code:
// Approach: Generate factorials 1!, 2!, ... only while the next multiplication stays at most the
//   limit.
#include <vector>
using namespace std;
vector<long long> factorialsUpTo(long long limit) {
    vector<long long> result;
    long long factorial = 1;
    for (long long next = 1; next <= limit / factorial; ++next) {
        factorial *= next;
        result.push_back(factorial);
    }
    return result;
}

s1-hashing-theory.code:
// Approach: Hash tables map keys to buckets, giving expected constant-time insert and lookup. Use
//   them to count frequencies.
#include <unordered_map>
#include <vector>
using namespace std;
int mostFrequentCount(const vector<int>& values) {
    unordered_map<int, int> frequency;
    int best = 0;
    for (int value : values) {
        int count = ++frequency[value];
        if (count > best) best = count;
    }
    return best;
}
